R=[
(2881,"क्विक पास्ता प्रिमावेरा","तीन आसान चरणों में आपके पास किडनी के अनुकूल, सेहतमंद व्यंजन तैयार है, जो पोषक तत्वों और फाइबर से भरपूर है, लेकिन पोटैशियम, सोडियम और फॉस्फोरस में कम है। क्विक पास्ता प्रिमावेरा को अपनी आसान, झटपट रेसिपी की सूची में जोड़ें।","2","1 कप",
["1/2 कप जमे हुए साबुत छोटे प्याज़","1/2 कप जमी हुई ब्रोकली, फूलगोभी, गाजर की मिक्स","1 कप पका हुआ तिरंगा स्पाइरल पास्ता","1/4 कप लाल शिमला मिर्च","2 छोटे चम्मच ऑलिव ऑयल","2 छोटे चम्मच बिना मसाले वाला राइस विनेगर","1/2 छोटा चम्मच Mrs. Dash® ओरिजिनल ब्लेंड हर्ब सीज़निंग","1 बड़ा चम्मच अजमोद (पार्सले)","2 नींबू की फाँक"],
["शिमला मिर्च और अजमोद (पार्सले) को काट लें।","जमी हुई सब्ज़ियों को पैकेट के निर्देशों के अनुसार तैयार करें।","तेल, सिरका और Mrs. Dash® हर्ब सीज़निंग को मिलाएँ। इसे सब्ज़ियों और गरम पास्ता के साथ मिलाएँ।","ऊपर से कटा हुआ अजमोद (पार्सले) छिड़कें। नींबू की फाँक के साथ परोसें।"],
["बचा हुआ हिस्सा ठंडे पास्ता सलाद के रूप में अच्छा लगता है। 1 बड़ा चम्मच इटैलियन सलाद ड्रेसिंग मिलाएँ, कम सोडियम वाला ब्रांड चुनें।"],
["1 स्टार्च","1 सब्ज़ी, मध्यम पोटैशियम","1 वसा"]),
(2882,"स्प्रिंग वेजिटेबल सूप","स्प्रिंग वेजिटेबल सूप में वसंत की सात पसंदीदा सब्ज़ियाँ शामिल हैं। पारंपरिक वेजिटेबल सूप की तुलना में इसमें सोडियम कम है और यह सब्ज़ियों की दो सर्विंग देता है।","5","1 कप",
["1 कप ताज़ी हरी बीन्स","3/4 कप अजवाइन (सेलरी)","1/2 कप प्याज़","1/2 कप गाजर","1/2 कप मशरूम","1/2 कप जमा हुआ मक्का (कॉर्न)","1 मध्यम रोमा टमाटर","2 बड़े चम्मच ऑलिव ऑयल","4 कप कम सोडियम वाला वेजिटेबल ब्रॉथ","1 छोटा चम्मच सूखी ओरेगैनो की पत्तियाँ","1 छोटा चम्मच लहसुन पाउडर","1/4 छोटा चम्मच नमक"],
["हरी बीन्स के सिरे और रेशे हटाएँ और 2-इंच के टुकड़ों में काट लें। अजवाइन (सेलरी), प्याज़, गाजर, मशरूम और टमाटर को छोटे टुकड़ों में काटें।","एक बड़े बर्तन में ऑलिव ऑयल गरम करें और अजवाइन (सेलरी) और प्याज़ को नरम होने तक भूनें।","बाकी सामग्री डालें और उबाल आने दें। आँच धीमी करें और 45 से 60 मिनट पकाएँ।"],
["चाहें तो पकाने के आख़िरी 20 मिनट में सूप में 1/4 से 1/2 कप कूसकूस या कोई दूसरा छोटा पास्ता डालें।","पोषक तत्वों के विश्लेषण में 1/4 छोटा चम्मच नमक शामिल है, लेकिन यह वैकल्पिक है।","ओरेगैनो और लहसुन पाउडर की मात्रा अपने स्वाद के अनुसार समायोजित करें।"],
["2 सब्ज़ी, मध्यम पोटैशियम","1 वसा"]),
(2887,"अंडों के साथ क्यूबाई शैली के चावल","धनिया पत्ती, जीरा और ओरेगैनो से स्वादिष्ट बने चावल, साथ में अंडों के साथ परोसे गए सुनहरे भूरे तले हुए केले (प्लांटेन), अंडों के साथ क्यूबाई शैली के चावल के इस स्वादिष्ट, कम पोटैशियम वाले संस्करण की सामग्री हैं।","4","2/3 कप चावल का मिश्रण, 3 प्लांटेन के टुकड़े, 2 अंडे",
["1 कप लंबे दाने वाले सफ़ेद चावल, कच्चे","1 तेज पत्ता","1 छोटा सफ़ेद प्याज़","1 मध्यम रोमा टमाटर","1 मध्यम प्लांटेन (कच्चा केला)","1 बड़ा चम्मच धनिया पत्ती","2 कलियाँ लहसुन","1 नींबू (लाइम)","1/2 छोटा चम्मच सूखा ओरेगैनो","1/4 छोटा चम्मच जीरा, या स्वादानुसार","1/2 छोटा चम्मच नमक","2 बड़े चम्मच ऑलिव ऑयल","8 बड़े अंडे"],
["चावल को राइस कुकर में या चूल्हे पर पैकेट के निर्देशों के अनुसार पकाएँ। पकाने से पहले चावल और पानी में तेज पत्ता डालें।","प्याज़ और टमाटर को काट लें। प्लांटेन का छिलका उतारें, फिर उसे तिरछा 12 स्लाइस में काटें। धनिया पत्ती और लहसुन को बारीक काट लें। नींबू (लाइम) को चार हिस्सों में काटें।","सूखा ओरेगैनो, जीरा और नमक एक बहुत छोटे कटोरे में मिलाएँ। अलग रख दें।","2 क्वार्ट के सॉसपैन में मध्यम आँच पर 1/2 बड़ा चम्मच ऑलिव ऑयल में प्याज़ और लहसुन को भूनें। जब लहसुन और प्याज़ महकने लगें, तो टमाटर डालकर 2 मिनट पकाएँ।","भाप में पके चावल और धनिया पत्ती डालकर चलाएँ। ऊपर से सूखे मसाले छिड़कें और तब तक चलाएँ जब तक सारी सामग्री आपस में मिल न जाए; अलग रख दें।","एक कड़ाही में 1/2 बड़ा चम्मच ऑलिव ऑयल गरम करें। प्लांटेन डालकर 2 मिनट पकाएँ, पलटें और सुनहरा भूरा होने तक पकाएँ।","अलग कड़ाही में मध्यम आँच पर 1 बड़ा चम्मच ऑलिव ऑयल गरम करें, अंडे फोड़कर डालें और पसंद के अनुसार पकने तक पकाएँ।","डिनर प्लेट पर 1/2 कप चावल और प्लांटेन के 3 टुकड़े रखें। हर हिस्से के ऊपर 2 अंडे रखें।","हर नींबू (लाइम) की फाँक का रस पूरे व्यंजन पर निचोड़ें।"],
["प्लांटेन का हिस्सा छोटा है क्योंकि प्लांटेन में पोटैशियम ज़्यादा होता है। यदि आप कम पोटैशियम वाले आहार पर नहीं हैं, तो प्लांटेन को बढ़ाकर 2 मध्यम या 1 बड़ा किया जा सकता है।","चावल पकाते समय 1:2 का अनुपात इस्तेमाल करें, यानी 1 कप चावल के लिए 2 कप पानी।","यदि आपके पास नींबू या नींबू (लाइम) न हो, तो अतिरिक्त स्वाद के लिए हर हिस्से पर 1/4 छोटा चम्मच सिरका छिड़कने की कोशिश करें।","चाहें तो मोहो सॉस के साथ परोसें।"],
["2 मांस","2 स्टार्च","1/2 फल, उच्च पोटैशियम","1 वसा"]),
(2890,"एशियन पत्तागोभी स्लॉ","कुरकुरा और स्वादिष्ट, इसी तरह टेक्सास की डीवीटा रीनल डाइटिशियन कॉर्बी अपनी एशियन पत्तागोभी स्लॉ की रेसिपी का वर्णन करती हैं। किडनी के अनुकूल पत्तागोभी, वॉटर चेस्टनट, प्याज़ और स्वाद बढ़ाने वाली अन्य सामग्री इस एशियाई शैली की साइड डिश को क्रॉनिक किडनी रोग वाले लोगों के लिए बेहतरीन विकल्प बनाती हैं।","8","1 कप",
["8 कप कतरी हुई पत्तागोभी","1/2 कप डिब्बाबंद, कटे वॉटर चेस्टनट","6 हरे प्याज़","2 बड़े चम्मच तिल","1/4 कप कैनोला तेल","1/4 कप एप्पल साइडर सिरका","1 बड़ा चम्मच चीनी","1/8 छोटा चम्मच काली मिर्च","1 कप चाउ मीन नूडल्स"],
["हरे प्याज़ को बारीक काट लें।","कतरी हुई पत्तागोभी, वॉटर चेस्टनट, हरे प्याज़ और तिल को बड़े कटोरे में रखें।","चीनी को सिरके में घोलें। सिरके को तेल में डालें और मिलने तक फेंटें।","इसे पत्तागोभी के मिश्रण पर डालें।","ड्रेसिंग को बराबर फैलाने के लिए उछालकर मिलाएँ।","कई घंटे या रातभर ठंडा करें।","परोसने से पहले चाउ मीन नूडल्स डालकर मिलाएँ।"],
["ग्रिल्ड चिकन, ब्रिस्केट या मछली के साथ परोसने पर यह एक बेहतरीन साइड डिश है।","चाउ मीन नूडल्स देखकर सबसे कम सोडियम वाला ब्रांड खरीदें।"],
["1/2 स्टार्च","1 सब्ज़ी, मध्यम पोटैशियम","2 वसा"]),
(2891,"युकाटन चिकन लाइम सूप","अपने खाने में थोड़ा \"चा-चा-चा\" जोड़ने के लिए तैयार हैं? किडनी के अनुकूल रेसिपी, युकाटन चिकन लाइम सूप, के लिए डीवीटा डाइटिशियन रॉबिन के साथ सीमा के दक्षिण की यात्रा पर चलिए।","4","1-1/2 कप",
["1/2 कप प्याज़","8 कलियाँ लहसुन","2 सेरानो मिर्च","1 मध्यम टमाटर","1-1/2 कप चिकन ब्रेस्ट, पका हुआ","2 कॉर्न टॉर्टिला, 6” आकार के","नॉनस्टिक कुकिंग स्प्रे","1 बड़ा चम्मच ऑलिव ऑयल","4 कप कम सोडियम वाला चिकन ब्रॉथ","1/4 छोटा चम्मच नमक","1 तेज पत्ता","1/4 कप नींबू (लाइम) का रस","1/4 कप ताज़ी धनिया पत्ती, कटी हुई","1/1 छोटा चम्मच काली मिर्च"],
["ओवन को 400º F पर पहले से गरम करें।","प्याज़ और धनिया पत्ती को बारीक काटें और लहसुन की कलियों को बारीक काट लें। मिर्चों को पतला स्लाइस करें। टमाटर को आधा काटें और छिलका व बीज निकाल दें। चिकन को कतर लें।","टॉर्टिला को पतली पट्टियों में काटें। टॉर्टिला की पट्टियों को बेकिंग शीट पर बिछाएँ और कुकिंग स्प्रे छिड़कें। 3 मिनट या हल्का टोस्ट होने तक बेक करें। ओवन से निकालकर ठंडा होने के लिए प्लेट में रख दें।","बड़े सॉसपैन में मध्यम आँच पर तेल गरम करें। प्याज़, लहसुन और मिर्चें डालें। प्याज़ के पारदर्शी होने तक पकाएँ।","टमाटर, ब्रॉथ, चिकन, नमक और तेज पत्ता डालें। 8 से 10 मिनट धीमी आँच पर पकाएँ।","नींबू (लाइम) का रस और धनिया पत्ती डालें। काली मिर्च से स्वाद बनाएँ।","चखें, और चाहें तो और नींबू (लाइम) का रस डालें।","ऊपर से टॉर्टिला की पट्टियाँ छिड़ककर परोसें।"],
["टॉर्टिला की जगह बारह बिना नमक वाले टॉर्टिला चिप्स इस्तेमाल किए जा सकते हैं। तैयारी में चरण #2 को छोड़ दें।","यदि नमक या बाउलन न मिलाया जाए, तो घर के बने चिकन स्टॉक में प्रति कप 30 से 60 मिग्रा सोडियम होता है। बिना नमक वाले या कम सोडियम वाले ब्रॉथ में प्रति कप 140 मिग्रा से कम सोडियम होता है। कम किए गए सोडियम वाले ब्रॉथ में प्रति कप 450 से 600 मिग्रा सोडियम होता है।","यदि इस रेसिपी में कम किए गए सोडियम वाला ब्रॉथ इस्तेमाल करें, तो ब्रॉथ की मात्रा घटाकर 2 कप करें, 1/4 छोटा चम्मच नमक न डालें और सोडियम कम रखने के लिए 2 कप पानी मिलाएँ।"],
["2-1/2 मांस","1 सब्ज़ी, मध्यम पोटैशियम","1/2 स्टार्च"]),
(2897,"तोरी (ज़ुकीनी) वैफ़ल","ये तोरी वैफ़ल एक बेहद स्वादिष्ट साइड डिश हैं। मुलायम और ज़ायकेदार!","6","1 वैफ़ल",
["3 कप कद्दूकस की हुई तोरी (ज़ुकीनी)","1/2 कप बारीक कटा प्याज़","1/4 कप कद्दूकस किया पारमेसन चीज़","1/2 कप मैदा (ऑल-पर्पज़ फ्लोर)","2 बड़े अंडे","3 बड़े चम्मच कम वसा वाला मेयोनेज़","1/2 छोटा चम्मच काली मिर्च","1/2 छोटा चम्मच पिसा ओरेगैनो","नॉनस्टिक कुकिंग स्प्रे"],
["कद्दूकस की हुई तोरी को छलनी या झरनी में रखकर जितना हो सके पानी निकाल दें। छलनी के ऊपर पेपर टॉवल से दबाकर कुछ पानी निचोड़ें।","सारी सामग्री को एक बड़े कटोरे में मिलाएँ। वैफ़ल आयरन को मध्यम आँच पर गरम करें।","वैफ़ल आयरन पर कुकिंग स्प्रे करें, बीच में लगभग 1/3 कप मिश्रण डालें और आयरन बंद करें। 4-5 मिनट पकाएँ और गरम रखने के लिए प्लेट में निकाल लें। बचे हुए मिश्रण के साथ यही दोहराएँ।"],
["दो मध्यम या 3 छोटी तोरी से लगभग 3 कप कद्दूकस की हुई तोरी मिलती है।","इन स्वादिष्ट तोरी वैफ़ल को मछली या अपने पसंदीदा चिकन व्यंजन के साथ साइड डिश के रूप में परोसें।","नमकीन स्वाद के लिए सावर क्रीम के साथ परोसें या मेपल सिरप से कुछ मिठास जोड़ें। आप इन वैफ़ल को नाश्ते के रूप में या अनोखे सुबह के नाश्ते के रूप में भी पसंद कर सकते हैं।"],
["1/2 स्टार्च","1 सब्ज़ी, मध्यम पोटैशियम","1 वसा"]),
(2902,"अकाई बेरी स्मूदी बाउल","शीरीन के अकाई बेरी स्मूदी बाउल से अपने रोज़ के फल, फाइबर और एंटीऑक्सीडेंट को बढ़ाएँ। इसे सुबह के नाश्ते, दोपहर के भोजन या पेट भरने वाले नाश्ते के रूप में बनाएँ और अपने आहार को सेहतमंद बढ़ावा दें।","2","1 कप",
["1 पैकेट जमा हुआ अकाई, बिना मीठा","1 कप जमी हुई मिक्स्ड बेरी, बिना मीठी","3/4 कप सादा 2% कम वसा वाला ग्रीक योगर्ट","1 छोटा चम्मच चिया बीज","1/2 कप राइस मिल्क, बिना मीठा, ओरिजिनल, क्लासिक","2 बड़े चम्मच रास्पबेरी","2 बड़े चम्मच ब्लूबेरी","1/4 ताज़ा नाशपाती"],
["जमी हुई अकाई प्यूरी को पैकेजिंग से निकालें और टुकड़ों में तोड़ लें।","अकाई के टुकड़े, जमी हुई मिक्स्ड बेरी, ग्रीक योगर्ट, चिया बीज और राइस मिल्क को ब्लेंडर में डालें।","चिकना होने तक ब्लेंड करें। गाढ़ाई इतनी होनी चाहिए कि चम्मच से खाई जा सके।","ब्लेंड किए मिश्रण को दो कटोरों में बराबर डालें।","ऊपर से रास्पबेरी, ब्लूबेरी और कटी हुई नाशपाती डालें।"],
["अकाई (उच्चारण आह-साई-ईई) बेरी दक्षिण अमेरिकी ताड़ के पेड़ से आती हैं। ये बेरी एंटीऑक्सीडेंट से भरपूर हैं और स्मूदी में एक बेहतरीन इज़ाफ़ा होती हैं।","कटा अनानास, बिना मीठे नारियल के फ्लेक्स, कोको निब्स या ग्रेनोला सीरियल जैसी अपनी पसंदीदा टॉपिंग डालकर अकाई बाउल को अपना बनाएँ।","टॉपिंग के लिए ताज़ी या जमी हुई रास्पबेरी और ब्लूबेरी इस्तेमाल करें।","यह रेसिपी खट्टी हो सकती है। मिठास के लिए आप शहद, स्टीविया या अपना पसंदीदा स्वीटनर मिला सकते हैं।","राइस मिल्क की जगह बादाम या सोया मिल्क जैसे कम फॉस्फोरस, कम पोटैशियम वाले दूध के विकल्प इस्तेमाल किए जा सकते हैं।"],
["1 दूध","1-1/2 फल, मध्यम पोटैशियम"]),
(2903,"सब्ज़ियों के साथ क्रीमी बोटाई पास्ता","यह स्वादिष्ट व्यंजन प्याज़ के कैरामेलाइज़ होने का इंतज़ार करने लायक है। यह किसी कुरकुरे पतझड़ के दिन या गरमियों की सुहानी शाम के भोजन के लिए बढ़िया है।","8","1 कप",
["3 मध्यम पीले प्याज़","2 बड़े चम्मच ऑलिव ऑयल, बाँटकर","1 बड़ा चम्मच बालसेमिक सिरका","10 औंस कटे मशरूम","5 औंस का डिब्बा ताज़ा पालक","1 कप हाफ एंड हाफ","2/3 कप कद्दूकस किया पारमेसन चीज़","8 औंस बोटाई (फ़ारफ़ेल) पास्ता"],
["प्याज़ को स्लाइस करके शुरू करें। प्याज़ को कैरामेलाइज़ करने के लिए बड़ी कड़ाही में 1 बड़ा चम्मच ऑलिव ऑयल गरम करें। कटे प्याज़ डालें और तेज़ आँच पर लगभग 10 मिनट लगातार चलाते हुए पकाएँ। प्याज़ बिना जले भूरे होने लगने चाहिए।","आँच को मध्यम करें और लगभग 10 मिनट तक प्याज़ को चलाते रहें। वे और ज़्यादा भूरे होने चाहिए, लेकिन अभी भी जले हुए नहीं।","आँच को फिर से मध्यम-धीमी करें और 10 मिनट तक पकाते रहें। ध्यान रखें कि प्याज़ पैन की तली में न चिपके। प्याज़ को कुल 30 मिनट पकाना चाहिए।","कड़ाही को आँच से उतारें और बालसेमिक सिरका छिड़कें। स्पैचुला से कड़ाही की तली को खुरचें और फिर कैरामेलाइज़्ड प्याज़ को प्लेट या कटोरे में निकाल लें।","उसी कड़ाही में बचा हुआ 1 बड़ा चम्मच ऑलिव ऑयल गरम करें और मशरूम डालें, मशरूम के नरम होने तक, लगभग 5 मिनट, पकाएँ।","पालक डालें और धीमी आँच पर चलाएँ जब तक पालक मुरझाना शुरू न हो जाए।","पालक और मशरूम के मिश्रण में हाफ एंड हाफ डालें। जल्दी से उबाल आने दें और फिर आँच धीमी करके उबालें।","2/3 कप पारमेसन चीज़ डालें और पिघलने तक चलाएँ। कैरामेलाइज़्ड प्याज़ को वापस कड़ाही में डालें।","फ़ारफ़ेल पास्ता को पैकेट के निर्देशों के अनुसार अल डेंटे पकाएँ। पानी निथारा हुआ फ़ारफ़ेल पास्ता कड़ाही में डालें और अच्छी तरह मिलाएँ।"],
["यदि समय कम हो, तो आप प्याज़ को पहले से कैरामेलाइज़ करके फ्रिज में रख सकते हैं।","पालक की जगह केल या रॉकेट (अरुगुला) इस्तेमाल किया जा सकता है।","अलग-अलग तरह के मशरूम जैसे शिटाके, क्रेमिनी या बटन मशरूम इस्तेमाल किए जा सकते हैं।","एक मध्यम प्याज़ का व्यास लगभग 2-1/2 इंच होता है।","इस व्यंजन को छोटे साइड सलाद या 1/2 कप कम पोटैशियम वाली सब्ज़ी के साथ परोसा जा सकता है।","इस व्यंजन से 8 सर्विंग बनती हैं, इसलिए इसे परिवार के रात के खाने के लिए इस्तेमाल किया जा सकता है या पूरे हफ़्ते बचे हुए खाने के रूप में रखा जा सकता है।"],
["1/2 मांस/प्रोटीन","1 स्टार्च","1 सब्ज़ी, उच्च पोटैशियम","1 वसा"]),
(2905,"अमरूद बारबेक्यू सॉस","अमरूद का पेस्ट इस प्यूर्टो रिको के बारबेक्यू सॉस को अनोखा स्वाद देता है। इसे ग्रिल्ड चिकन या स्टेक पर आज़माएँ।","8","2 बड़े चम्मच",
["2 कलियाँ लहसुन","1/4 कप प्याज़","1 बड़ा चम्मच ऑलिव ऑयल","1/2 कप अमरूद का पेस्ट","1/4 कप पानी","3 बड़े चम्मच केचप या टमाटर सॉस","2 बड़े चम्मच ब्राउन शुगर","1/2 बड़ा चम्मच प्याज़ पाउडर","1/2 छोटा चम्मच स्मोक्ड पैपरिका"],
["लहसुन को बारीक काटें और प्याज़ को छोटे टुकड़ों में काट लें। कड़ाही में तेल गरम करें और कटा हुआ लहसुन और प्याज़ डालकर पारदर्शी होने तक पकाएँ।","अमरूद का पेस्ट और पानी डालें और चिकना होने तक और पेस्ट घुलने तक चलाएँ।","बाकी सामग्री डालें और धीमी से मध्यम आँच पर चिकना होने तक, लगभग 5 से 10 मिनट, पकाएँ। ध्यान रखें कि सॉस में उबाल न आए।","कड़ाही को आँच से उतारें और ठंडा होने दें।","सॉस को इस्तेमाल होने तक जार या ढके हुए डिब्बे में रखें।"],
["पकाने के आख़िर में मांस पर सॉस ब्रश से लगाएँ।","अमरूद बारबेक्यू सॉस को प्यूर्टो रिकन स्टाइल चिकन स्क्यूअर्स या ग्रिल्ड बीफ़ पर आज़माएँ।"],
["1/2 वसा","1 उच्च कैलोरी"]),
(2907,"अनानास बार्स","क्या आप जानते हैं कि अनानास दुनिया के पसंदीदा उष्णकटिबंधीय फलों में से एक है, जो केवल केले के बाद आता है? कुरकुरा, मीठा और फाइबर से भरपूर, हर अनानास में विटामिन, खनिज और एंज़ाइम होते हैं जो पाचन तंत्र के लिए आसान होते हैं। इन सब खूबियों के साथ, इसमें कोई हैरानी नहीं कि इलिनॉय की डीवीटा डाइटिशियन जेनिफ़र ने इस अद्भुत फल पर आधारित मिठाई की कल्पना की और उसे अनानास बार्स नाम दिया, जो सबके लिए किडनी के अनुकूल एक स्वादिष्ट व्यंजन है।","24","1 बार (लगभग 3” x 3”)",
["2-1/2 कप मैदा (ऑल-पर्पज़ व्हाइट फ्लोर)","1 कप Crisco® शॉर्टनिंग","1/2 कप कम वसा वाला दूध या दूध का विकल्प","20 औंस डिब्बाबंद कुचला हुआ अनानास, पानी निथारा हुआ","7 बड़े चम्मच कॉर्नस्टार्च","1 कप दानेदार चीनी","1 कप पिसी चीनी (पाउडर शुगर)","1/4 कप मार्जरीन","8 औंस क्रीम चीज़","1 बड़ा चम्मच वैनिला","मैराशिनो चेरी (वैकल्पिक)"],
["ओवन को 400° F पर पहले से गरम करें।","मैदा, शॉर्टनिंग और दूध या दूध के विकल्प को मिलाएँ।","इसे बिना चिकनाई लगे 17” X 11” के जेली रोल पैन में दबाकर बिछाएँ।","अनानास, कॉर्नस्टार्च और दानेदार चीनी को आपस में मिलाएँ।","इसे क्रस्ट पर डालें और 20 मिनट बेक करें। ठंडा होने दें।","पिसी चीनी, मार्जरीन, क्रीम चीज़ और वैनिला को आपस में फेंटकर क्रीमी बनाएँ।","इसे ठंडे क्रस्ट पर फैलाएँ; ठंडा करें और फिर चौकोर टुकड़ों में काटें।","चाहें तो ऊपर से कटी मैराशिनो चेरी डालें।"],
["जूस या सिरप में डिब्बाबंद अनानास इस्तेमाल करें; दोनों इस रेसिपी में अच्छे रहते हैं।"],
["1/2 स्टार्च","1/2 डेयरी","1 उच्च कैलोरी","2 वसा"]),
(2909,"कैसरोल या पॉट पाई के लिए व्हाइट ग्रेवी","कैसरोल और पॉट पाई की रेसिपी में अक्सर डिब्बाबंद सूप की ज़रूरत होती है, लेकिन उसमें सोडियम ज़्यादा होता है। अगली बार इसकी जगह कैसरोल और पॉट पाई के लिए व्हाइट ग्रेवी की हमारी किडनी के अनुकूल रेसिपी आज़माएँ।","6","2-1/2 बड़े चम्मच",
["2 बड़े चम्मच बिना नमक का मार्जरीन","1/4 कप प्याज़","1 बड़ा चम्मच अजवाइन (सेलरी)","2 बड़े चम्मच मैदा (ऑल-पर्पज़ व्हाइट फ्लोर)","1 छोटा चम्मच पोल्ट्री सीज़निंग","1/4 छोटा चम्मच काली मिर्च","1 कप तरल नॉन-डेयरी क्रीमर"],
["प्याज़ और अजवाइन (सेलरी) को बारीक काट लें।","नॉनस्टिक फ्राइंग पैन में मार्जरीन पिघलाएँ।","मार्जरीन में प्याज़ और अजवाइन (सेलरी) को नरम होने तक भूनें। मैदा, पोल्ट्री सीज़निंग और काली मिर्च डालकर चलाएँ। धीमी आँच पर एक मिनट चलाएँ।","नॉन-डेयरी क्रीमर को 1/4 कप करके डालें और गाढ़ा होने तक चलाएँ। कैसरोल या पॉट पाई में इस्तेमाल के लिए तैयार।"],
["इस ग्रेवी को डिब्बाबंद क्रीम सूप की जगह इस्तेमाल करें, क्योंकि इसमें सोडियम की मात्रा बहुत कम है। अलग-अलग जड़ी-बूटियाँ और मसाले डालकर स्वाद बदलें।"],
["1/2 नॉन-डेयरी दूध का विकल्प"]),
(2911,"तोरी (ज़ुकीनी) मफ़िन","क्या आप ऐसी सेहतमंद मफ़िन ढूँढ रहे हैं जो आपकी रोज़ की सब्ज़ियों में से कुछ हिस्सा चुपके से शामिल करने में मदद करे? डीवीटा रीनल डाइटिशियन आइलीन अपनी तोरी मफ़िन की रेसिपी साझा करती हैं। यह किडनी के अनुकूल है और आपके लिए अच्छी है।","28","1 मफ़िन",
["3 कप मैदा (ऑल-पर्पज़ व्हाइट फ्लोर)","3/4 कप चीनी या Splenda दानेदार स्वीटनर","1-1/2 छोटे चम्मच पंपकिन पाई स्पाइस","1-1/2 छोटे चम्मच बेकिंग सोडा","1 छोटा चम्मच नमक","4 अंडे","2 कप कद्दूकस की हुई तोरी (ज़ुकीनी)","3/4 कप शहद","1/3 कप तेल","1/3 कप बिना मीठी एप्पलसॉस","2 बड़े चम्मच नींबू का रस","1 छोटा चम्मच वैनिला एक्सट्रैक्ट"],
["ओवन को 375°F पर पहले से गरम करें।","एक बड़े कटोरे में मैदा, चीनी, पंपकिन पाई स्पाइस, बेकिंग सोडा और नमक मिलाएँ।","एक मध्यम कटोरे में अंडों को हल्का फेंटें। उसमें तोरी, शहद, तेल, एप्पलसॉस, नींबू का रस और वैनिला मिलाएँ।","तरल मिश्रण को मैदे के मिश्रण में बस इतना चलाएँ कि मैदा गीला हो जाए।","मफ़िन टिन पर चिकनाई लगाएँ या पेपर लाइनर इस्तेमाल करें। हर कप को 3/4 भरें।","15 से 20 मिनट या टूथपिक साफ़ निकलने तक बेक करें।"],
["सूखी सामग्री में अपने पसंदीदा प्रोटीन पाउडर के 7 बड़े चम्मच मिलाकर प्रोटीन की मात्रा 3 ग्राम तक बढ़ाएँ।","यदि चीनी की जगह Splenda इस्तेमाल करें, तो कार्बोहाइड्रेट घटकर 18 ग्राम और 1 कार्बोहाइड्रेट चॉइस हो जाता है।","यदि ज़्यादा कैलोरी चाहिए, तो मफ़िन के ऊपर क्रीम चीज़ फ्रॉस्टिंग लगाएँ और मिठाई के रूप में परोसें।","चाहें तो 2/3 कप एप्पलसॉस इस्तेमाल करें और तेल न डालें, या 2/3 कप तेल इस्तेमाल करें और एप्पलसॉस न डालें।"],
["1 स्टार्च","1/2 उच्च कैलोरी","1/2 वसा"]),
(2913,"टोस्ट पर क्रीम्ड एग्स","टोस्ट पर क्रीम्ड एग्स डीवीटा डाइटिशियन एमी की पीढ़ी-दर-पीढ़ी चली आ रही पारिवारिक कुकबुक की एक पुरानी रेसिपी है। इसे एक बार आज़माएँ और हो सकता है आप इसके दीवाने हो जाएँ! यह उच्च कैलोरी वाला व्यंजन आपका पेट भरने और आपके भोजन में उच्च गुणवत्ता वाला प्रोटीन जोड़ने के लिए पक्का है।","4","1 कप क्रीम्ड एग्स + 1 स्लाइस टोस्ट",
["6 बड़े अंडे","3 बड़े चम्मच बिना नमक का मक्खन","1/3 कप मैदा (ऑल-पर्पज़ फ्लोर)","1-1/2 कप बिना मीठा, सादा बादाम का दूध","1/2 बड़ा चम्मच पीली सरसों (येलो मस्टर्ड)","4 औंस क्रीम चीज़","1/8 छोटा चम्मच काली मिर्च","4 मोटे स्लाइस सफ़ेद ब्रेड"],
["अंडों को 12 मिनट तक उबालें। आँच से उतारें, पानी निथार दें और ठंडे पानी से ढक दें। उबले अंडों का छिलका उतारकर काट लें और अलग रख दें।","एक सॉसपैन में मध्यम-धीमी आँच पर मक्खन और मैदा मिलाएँ। अच्छी तरह मिलने तक लगातार चलाएँ।","मक्खन और मैदे के मिश्रण में बादाम का दूध, सरसों, क्रीम चीज़ और काली मिर्च डालें। गाढ़ा होने तक लगातार चलाएँ।","अंडों को सॉस में डालें और हल्की गरम आँच पर रखें।","ब्रेड को टोस्ट करें।","अंडों का मिश्रण टोस्ट पर डालें और परोसें।"],
["चाहें तो ज़्यादा स्वाद के लिए सूखा सोआ (डिल) या लहसुन पाउडर डालें।","प्रति स्लाइस सबसे कम सोडियम वाली ब्रेड खोजें।"],
["1-1/2 मांस","1-1/2 स्टार्च","4 वसा"]),
(2914,"क्रीम चीज़ और एप्पलसॉस भरावन वाला फ्रेंच टोस्ट","क्रीम चीज़, एप्पलसॉस और दालचीनी को साबुत गेहूँ की ब्रेड के 2 स्लाइस और अंडे के सफ़ेद भाग के बीच सैंडविच की तरह भरा जाता है। क्रीम चीज़ और एप्पलसॉस भरावन वाले फ्रेंच टोस्ट को अपनी सहेजी हुई पसंदीदा रेसिपी में जोड़ें।","1","1",
["साबुत गेहूँ की ब्रेड के 2 स्लाइस","4 बड़े चम्मच तरल अंडे का सफ़ेद भाग, बाँटकर","1 औंस क्रीम चीज़","2 बड़े चम्मच बिना मीठी एप्पलसॉस","स्वादानुसार दालचीनी"],
["नॉन-स्टिक कड़ाही को तेज़-मध्यम आँच पर पहले से गरम करें।","एक कटोरे में 2 बड़े चम्मच अंडे का सफ़ेद भाग डालें, फिर ब्रेड का एक स्लाइस रखें। ध्यान रखें कि अंडा ब्रेड की केवल एक तरफ़ लगे। अंडे को ब्रेड में सोखने दें।","ब्रेड को अंडे वाली तरफ़ नीचे करके कड़ाही में रखें।","कड़ाही में रखी ब्रेड पर क्रीम चीज़ और एप्पलसॉस डालें और ऊपर से दालचीनी छिड़कें।","दूसरे स्लाइस के साथ चरण 2 दोहराएँ और उसे कड़ाही वाले स्लाइस के ऊपर, अंडे वाली तरफ़ ऊपर करके रखें","जब पहले ब्रेड स्लाइस का नीचे का हिस्सा भूरा हो जाए, तो उसे पलटें और दूसरी तरफ़ भी भूरा करें।","प्लेट में निकालें और अपनी पसंद का सिरप ऊपर डालें।"],
["एक अंडे की जर्दी में 66 मिग्रा फॉस्फोरस होता है। एंजेला सिर्फ़ अंडे का सफ़ेद भाग इस्तेमाल करने की सलाह देती हैं, ताकि आप फाइबर बढ़ाने के लिए साबुत गेहूँ की ब्रेड इस्तेमाल कर सकें और फिर भी फॉस्फोरस कम रख सकें। सफ़ेद ब्रेड के एक स्लाइस में 25 मिग्रा फॉस्फोरस होता है; साबुत गेहूँ की ब्रेड के एक स्लाइस में 57 मिग्रा फॉस्फोरस होता है।"],
["1 मांस","2 स्टार्च","1 वसा"]),
(2917,"तिल वाले राइस क्रैकर","तिल वाले राइस क्रैकर चावल के आटे, तिल, बेकिंग पाउडर, कैनोला तेल और पानी का मिश्रण हैं, जिन्हें आसानी से चपटा बेला और बेक किया जाता है और एक स्वादिष्ट नाश्ता तैयार होता है।","6","1/2 कप या 2 औंस",
["1 कप सफ़ेद चावल का आटा","1 छोटा चम्मच बेकिंग पाउडर","2 बड़े चम्मच तिल","1 बड़ा चम्मच कैनोला तेल","8 बड़े चम्मच पानी","1/8 छोटा चम्मच नमक (वैकल्पिक)"],
["ओवन को 400° F पर पहले से गरम करें।","नमक को छोड़कर सारी सामग्री को सूची के क्रम में एक बड़े मिक्सिंग बाउल में डालें।","साफ़ हाथों या दस्तानों से सामग्री को मिलाएँ और आटे की एक गोली बना लें।","एक समतल सतह पर पार्चमेंट पेपर की एक शीट बिछाएँ। आटे की गोली को बीच में रखें।","उसे पार्चमेंट पेपर की दूसरी शीट से ढक दें और बेलन से आटे को जितना हो सके उतना पतला बेलें। ऊपर वाला पार्चमेंट पेपर हटाकर बाद के इस्तेमाल के लिए अलग रख दें।","चपटे आटे वाले निचले पार्चमेंट पेपर को बड़ी शीट पैन पर रखें।","10 से 12 मिनट बेक करें। ओवन से निकालें, दूसरा पार्चमेंट पेपर सपाट बिछाएँ और आटे को सावधानी से पार्चमेंट पेपर पर पलट दें। शीट पैन पर रखें। 1/8 छोटा चम्मच नमक छिड़कें और हल्का टोस्ट और कुरकुरा होने तक 10 से 12 मिनट और बेक करें।","पूरी तरह ठंडा होने दें। छोटे क्रैकर बनाने के लिए काटें या सीधे तोड़ लें।"],
["ज़्यादा एक समान क्रैकर बनाने के लिए, बेक करने से पहले आटे पर चाकू से मनचाहे आकार और साइज़ के निशान बनाएँ। 10 से 12 मिनट बाद पूरा काटकर पलट दें। किनारे जल्दी भूरे हो सकते हैं, 9 से 10 मिनट बाद जाँचें।","चाहें तो तिल की मात्रा 1 बड़ा चम्मच कर लें।"],
["1-1/2 स्टार्च","1/2 वसा"]),
]
